package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses any change to a claim belonging to a closed period: one whose due-by falls inside it. */
public class RefuseClosedClaim {
    public void check(@Val Claim claim, PeriodRepository periods) throws BadRequestException {
        if (periods.closedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new BadRequestException(RefuseClosedDate.CLOSED);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@Val SheetResponse sheet, @PathVariable("claimId") String claimId,
            ClaimRepository repository, Out<Claim> claim) throws BadRequestException {
        Claim found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id: no such claim
        }
        if (found == null) {
            throw new BadRequestException("No such claim on this sheet");
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.access;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses any change by a viewer on the sheet, or to an archived sheet, before it touches the store. */
public class RefuseViewer {
    public void refuse(@Val SheetResponse sheet, @Val ChangedBy by, RoleRepository roles,
            SheetRepository sheets) throws BadRequestException {
        if (roles.isViewer(sheet.id(), by.name())) {
            throw new BadRequestException("A viewer may not change anything on this sheet");
        }
        sheets.refuseArchived(sheet.id());
    }
}
